css:
.ll { display: flex; flex-direction: column; gap: 14px; }
.ll-a { display: flex; flex-direction: column; gap: 6px; padding: 22px 24px; border-radius: 12px; background: rgba(4,28,48,0.7); border: 1px solid rgba(255,255,255,0.1); text-decoration: none; transition: border-color .25s ease; }
.ll-a:hover { border-color: #00cdfd; }
.ll-t { font-size: 17px; font-weight: 600; color: #f4fbff; }
.ll-d { font-size: 14px; line-height: 1.55; color: #9fb4c6; }
